describe('Form Accessibility Tests', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should have associated labels for all form fields', () => {
        cy.get('form').within(() => {
            cy.get('input, select, textarea').each(($field) => {
                const id = $field.prop('id');
                const label = cy.get(`label[for="${id}"]`);
                label.should('exist');
                label.should('not.be.empty');
            });
        });
    });

    it('should not have any form fields without associated labels', () => {
        cy.get('form').within(() => {
            cy.get('input, select, textarea').each(($field) => {
                const id = $field.prop('id');
                cy.get(`label[for="${id}"]`).should('exist');
            });
        });
    });
});
